import{_ as e,o,c as a,ag as n}from"./chunks/framework.BIas3y6W.js";const m=JSON.parse('{"title":"Week 3 Lab — Save Points and Game in an Hour","description":"","frontmatter":{"source":"weeks/03-prompting-and-save-points/lab.md"},"headers":[],"relativePath":"weeks/03-prompting-and-save-points/lab.md","filePath":"weeks/03-prompting-and-save-points/lab.md"}'),s={name:"weeks/03-prompting-and-save-points/lab.md"};function i(r,t,d,h,l,c){return o(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="week-3-lab--save-points-and-game-in-an-hour" tabindex="-1">Week 3 Lab — Save Points and Game in an Hour <a class="header-anchor" href="#week-3-lab--save-points-and-game-in-an-hour" aria-label="Permalink to &quot;Week 3 Lab — Save Points and Game in an Hour&quot;">​</a></h1><blockquote><p><strong>Goal:</strong> in Studio A, set up your game file and practice the save-point workflow once, slowly: a four-part prompt, a diff, a commit with an <code>Assisted-by:</code> line, your History. In Studio B, build a small browser game in one timed hour, one step at a time, with a save point after every working step. <strong>Time:</strong> Studio A lab about 30 minutes, Studio B lab about 70 minutes. <strong>You need:</strong> your <code>[your-username].github.io</code> repository from week 2, a chat assistant with a live preview (see the <a href="./../../TOOLS.html">Tool Handout</a>), and the <a href="./game-menu.html">game menu</a>.</p></blockquote><p><strong>AI-use key:</strong> 🟢 AI on: use AI freely · 🟡 AI limited: the AI may comment or hint, but the work is yours · 🔴 AI off: close the AI tabs and work alone.</p><p>Studios are graded on effort, not polish (<a href="./../../assessment/rubrics.html#in-class-work-and-participation">rubric</a>): a part that didn&#39;t work, with the exact error and what you tried, still counts.</p><p>This week you use the full <a href="./../../resources/safe-loop.html">Safe Loop</a> for the first time: <strong>Describe → Plan → Step → Test → Read → Commit</strong>.</p><p>Stuck for more than 5 minutes? Check <a href="#troubleshooting">Troubleshooting</a>, ask a neighbor, then raise your hand. Using a screen reader or only a keyboard? The <a href="./../../resources/accessibility.html">Screen reader and keyboard guide</a> covers github.dev and the GitHub website.</p><h2 id="words-youll-use-this-week" tabindex="-1">Words you&#39;ll use this week <a class="header-anchor" href="#words-youll-use-this-week" aria-label="Permalink to &quot;Words you&#39;ll use this week&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Word</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Repository</strong> (repo)</td><td>A project folder that git tracks. Yours is <code>[your-username].github.io</code></td></tr><tr><td><strong>Commit</strong></td><td>A save point: a snapshot of your files, with a message saying what changed</td></tr><tr><td><strong>Commit message</strong></td><td>The description of a commit, e.g. <code>Step 2: snake moves with arrow keys</code></td></tr><tr><td><strong>History</strong></td><td>The list of all commits, newest first</td></tr><tr><td><strong>Diff</strong></td><td>What changed between two versions: removed lines in red (marked <code>-</code>), added lines in green (marked <code>+</code>)</td></tr><tr><td><strong>Hash</strong></td><td>A commit&#39;s ID, such as <code>4f2a9c1</code> (the short version is 7 characters)</td></tr><tr><td><strong>github.dev</strong></td><td>A code editor (VS Code) that runs in your browser and edits your repository directly. It can&#39;t run programs</td></tr><tr><td><strong><code>Assisted-by:</code> line</strong></td><td>A last line in a commit message naming the AI tool that helped, e.g. <code>Assisted-by: Gemini</code></td></tr></tbody></table><p>More in the <a href="./../../resources/git-cheatsheet.html">Git Cheat Sheet</a> and the <a href="./../../resources/glossary.html">Glossary</a>.</p><hr><h2 id="studio-a--save-points-75-min" tabindex="-1">Studio A — Save points (75 min) <a class="header-anchor" href="#studio-a--save-points-75-min" aria-label="Permalink to &quot;Studio A — Save points (75 min)&quot;">​</a></h2><p>The studio opens with a recap, the concept talk and a live demo (30 minutes), then:</p><table tabindex="0"><thead><tr><th>Part</th><th>What you do</th><th>Time</th><th>Core or If time</th><th>AI use</th></tr></thead><tbody><tr><td>A1</td><td>Open github.dev and create your game file</td><td>10 min</td><td>Core</td><td>Not needed</td></tr><tr><td>A2</td><td>One small change, one save point</td><td>15 min</td><td>Core</td><td>🟢 AI on · you write the prompt</td></tr><tr><td>A3</td><td>Read your History</td><td>5 min</td><td>Core</td><td>Not needed</td></tr><tr><td>A4</td><td>Get ready for Game in an Hour</td><td>5 min</td><td>If time</td><td>Not needed</td></tr></tbody></table><p>The studio ends with a <strong>checkpoint share</strong> and the Week 3 exit ticket (🔴 AI off). The exit ticket is here, not in Studio B, because the game fills Studio B.</p><h3 id="part-a1--open-githubdev-and-create-your-game-file-10-min" tabindex="-1">Part A1 — Open github.dev and create your game file (10 min) <a class="header-anchor" href="#part-a1--open-githubdev-and-create-your-game-file-10-min" aria-label="Permalink to &quot;Part A1 — Open github.dev and create your game file (10 min)&quot;">​</a></h3><p><strong>Why:</strong> chat assistants forget and previews disappear. Your repository keeps every version you commit.</p><ol><li><p>Open your repository on github.com: <code>https://github.com/[your-username]/[your-username].github.io</code>.</p></li><li><p>Press the <strong>.</strong> (period) key, with the cursor not in a text box. <strong>github.dev</strong> opens: a code editor in your browser. (Or change <code>github.com</code> to <code>github.dev</code> in the address bar.) Sign in if asked.</p></li><li><p>In the <strong>Explorer</strong> panel on the left, hover over your repository&#39;s name and click the <strong>New File</strong> icon. Type <code>game/index.html</code> and press Enter. The <code>/</code> creates a folder called <code>game</code>.</p></li><li><p>Type this placeholder <strong>by hand</strong>:</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;!</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">DOCTYPE</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> html</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;My game&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">h1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Game coming soon&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">h1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div></li><li><p>Save with <strong>Ctrl+S</strong> (Windows, ChromeOS) or <strong>Cmd+S</strong> (Mac).</p></li><li><p>Open <strong>Source Control</strong>: the icon of three connected dots in the left bar, or <strong>Ctrl+Shift+G</strong> (on a Mac, <strong>Control+Shift+G</strong>). Your file appears under <strong>Changes</strong>. Click it to see the <strong>diff</strong>: every line is green because it&#39;s new.</p></li><li><p>In the <strong>Message</strong> box, type <code>Add game placeholder</code>. Click <strong>Commit &amp; Push</strong>. If github.dev asks whether to stage all changes and commit them directly, choose <strong>Yes</strong>.</p></li><li><p>Wait a minute, then visit <code>https://[your-username].github.io/game/</code>.</p></li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Menus move. If a button has a different name, look for the same idea (a message box and a commit button), or ask your assistant where it is in github.dev today.</p></div><p>✅ <strong>Checkpoint:</strong> <code>https://[your-username].github.io/game/</code> shows &quot;Game coming soon&quot;, and the <strong>Projects</strong> link on your home page now leads there instead of a 404.</p><h3 id="part-a2--one-small-change-one-save-point-15-min" tabindex="-1">Part A2 — One small change, one save point (15 min) <a class="header-anchor" href="#part-a2--one-small-change-one-save-point-15-min" aria-label="Permalink to &quot;Part A2 — One small change, one save point (15 min)&quot;">​</a></h3><p>🟢 AI on. You write the prompt yourself; the AI writes the code.</p><p><strong>Why:</strong> you&#39;ll make about ten commits in Studio B&#39;s hour, against the clock. Do the whole loop once now, slowly, while nothing is at stake.</p><ol><li><p><strong>Describe.</strong> Pick one small change to your home page, for example a footer line &quot;Last updated [month year]&quot;, links that change color when you hover over them, or a &quot;Back to top&quot; link. In your scratch note, write a four-part prompt for it:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: [one small change].</span></span>
<span class="line"><span>Context: Here is my current index.html: [paste the complete file].</span></span>
<span class="line"><span>Constraints: Change only what this needs and keep everything else exactly as it is. Give me the complete updated file in one code block.</span></span>
<span class="line"><span>Done when: [what you&#39;ll see on the page, checkable in under a minute].</span></span></code></pre></div><p>To get the complete file, open <code>index.html</code> on github.com and click <strong>Copy raw file</strong> (two overlapping squares, top right of the code).</p></li><li><p><strong>Step and Test.</strong> Send it to your assistant. In the preview, check your &quot;Done when&quot;, and check that the rest of the page still looks the same.</p></li><li><p><strong>Read.</strong> Copy the complete file. In github.dev, click into <code>index.html</code>, select everything (<strong>Ctrl+A</strong> / <strong>Cmd+A</strong>), paste and save. In <strong>Source Control</strong>, click the file to see the diff. Does the size of the change match the size of what you asked for? If the AI changed something you didn&#39;t ask for, ask it why before you commit.</p></li><li><p><strong>Commit, with an <code>Assisted-by:</code> line.</strong> The first line says what changed, as always. Then a blank line. Then the tool:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Add &quot;Last updated&quot; line to the footer</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Assisted-by: Gemini</span></span></code></pre></div><p>In github.dev&#39;s <strong>Message</strong> box, type the first line, press <strong>Enter</strong> twice to add a blank line, then type <code>Assisted-by: [tool]</code>. (<strong>Ctrl+Enter</strong> / <strong>Cmd+Enter</strong> commits; plain <strong>Enter</strong> adds a new line.) Then <strong>Commit &amp; Push</strong>. On github.com (pencil icon), the first line goes in <strong>Commit message</strong> and <code>Assisted-by: [tool]</code> in <strong>Extended description</strong>.</p></li></ol><p>Use the <code>Assisted-by:</code> line when an AI wrote or shaped the change; if you used two tools, add one line for each. Leave it off for changes you made entirely by hand. More in the Safe Loop&#39;s <a href="./../../resources/safe-loop.html#the-assisted-by-line">Assisted-by section</a>.</p><p>✅ <strong>Checkpoint:</strong> your live home page shows the change a minute later, and the commit&#39;s message ends with <code>Assisted-by: [tool]</code>.</p><h3 id="part-a3--read-your-history-5-min" tabindex="-1">Part A3 — Read your History (5 min) <a class="header-anchor" href="#part-a3--read-your-history-5-min" aria-label="Permalink to &quot;Part A3 — Read your History (5 min)&quot;">​</a></h3><ol><li>On github.com, open your repository, then <code>index.html</code>, and click <strong>History</strong> (top right of the file, with a clock icon). You&#39;ll see every commit that changed this file, newest first.</li><li>Click your commit from Part A2. Read the red and green lines. Check that the <code>Assisted-by:</code> line is there, under the message.</li><li>Find the commit&#39;s short <strong>hash</strong> (like <code>4f2a9c1</code>) and copy it into your scratch note, with the commit&#39;s link.</li></ol><p>Every row in this list can be brought back. To undo a bad change, you don&#39;t delete its commit: you add a <strong>new</strong> commit that puts the file back the way it was, so the history keeps both. That&#39;s what <code>git revert</code> does. Next week you&#39;ll break your game on purpose and do exactly that.</p><p>✅ <strong>Checkpoint:</strong> you have the link to your <code>Assisted-by:</code> commit and its hash in your scratch note.</p><h3 id="part-a4--get-ready-for-game-in-an-hour-5-min-if-time" tabindex="-1">Part A4 — Get ready for Game in an Hour (5 min, if time) <a class="header-anchor" href="#part-a4--get-ready-for-game-in-an-hour-5-min-if-time" aria-label="Permalink to &quot;Part A4 — Get ready for Game in an Hour (5 min, if time)&quot;">​</a></h3><ul><li>Pick your game and a backup from the <a href="./game-menu.html">game menu</a>. Read its sample plan and its &quot;Watch out for&quot; line.</li><li>Start a new scratch note for Studio B, titled with your game&#39;s name, so you&#39;re ready to paste a plan into it.</li><li>Check that your preview assistant is signed in and has its live preview on.</li></ul><h3 id="checkpoint-share-and-exit-ticket-end-of-studio-a" tabindex="-1">Checkpoint share and exit ticket (end of Studio A) <a class="header-anchor" href="#checkpoint-share-and-exit-ticket-end-of-studio-a" aria-label="Permalink to &quot;Checkpoint share and exit ticket (end of Studio A)&quot;">​</a></h3><p>Post the link to your <code>Assisted-by:</code> commit where your instructor asks, with the game you picked (for example &quot;Snake, link: …&quot;). Stuck? Post the exact blocker instead: that counts too.</p><p>Then do the Week 3 exit ticket (10 min, 🔴 AI off). It&#39;s scored for completion, not correctness.</p><p><strong>Working alone?</strong> Write the link and your game choice in your scratch note.</p><hr><h2 id="studio-b--game-in-an-hour-75-min" tabindex="-1">Studio B — Game in an Hour (75 min) <a class="header-anchor" href="#studio-b--game-in-an-hour-75-min" aria-label="Permalink to &quot;Studio B — Game in an Hour (75 min)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Part</th><th>What you do</th><th>Time</th><th>Core or If time</th><th>AI use</th></tr></thead><tbody><tr><td>B1</td><td>Ready check</td><td>5 min</td><td>Core</td><td>Not needed</td></tr><tr><td>B2</td><td><strong>Game in an Hour</strong> (timed)</td><td>60 min</td><td>Core</td><td>🟢 AI on</td></tr><tr><td>B3</td><td>Play-test swap and checkpoint share</td><td>10 min</td><td>Core</td><td>Not needed</td></tr></tbody></table><h3 id="part-b1--ready-check-5-min" tabindex="-1">Part B1 — Ready check (5 min) <a class="header-anchor" href="#part-b1--ready-check-5-min" aria-label="Permalink to &quot;Part B1 — Ready check (5 min)&quot;">​</a></h3><p>Before the timer starts, have three tabs open: <strong>github.dev</strong> on your repository with <code>game/index.html</code> open, your <strong>assistant</strong> in a new chat with the live preview available, and the <a href="./game-menu.html">game menu</a>. Keep your scratch note beside them.</p><p>Your instructor starts a visible 60-minute timer. Working alone? Set one on your phone. Rather work without the clock (for example with a screen reader)? Anyone may do it untimed; see <a href="./../../resources/accessibility.html#timed-builds">Timed builds</a> for tips and game choices.</p><h3 id="part-b2--game-in-an-hour-60-min-timed" tabindex="-1">Part B2 — Game in an Hour (60 min, timed) <a class="header-anchor" href="#part-b2--game-in-an-hour-60-min-timed" aria-label="Permalink to &quot;Part B2 — Game in an Hour (60 min, timed)&quot;">​</a></h3><p>🟢 AI on.</p><p><strong>The goal is a working game built in small steps, not a perfect game.</strong> Game in an Hour is graded on effort, not on whether you finish (<a href="./../../assessment/rubrics.html#in-class-work-and-participation">rubric</a>). A game that stops at step 3 with clean save points beats a broken five-step game, and it&#39;s a full-credit hour.</p><table tabindex="0"><thead><tr><th>Minutes</th><th>Stage</th></tr></thead><tbody><tr><td>0–8</td><td>Pick a game and plan it</td></tr><tr><td>8–25</td><td>Steps 1 and 2</td></tr><tr><td>25–40</td><td>Step 3</td></tr><tr><td>40–52</td><td>Step 4</td></tr><tr><td>52–60</td><td>Step 5, or polish</td></tr></tbody></table><h4 id="pick-a-game-and-plan-it-minutes-08" tabindex="-1">Pick a game and plan it (minutes 0–8) <a class="header-anchor" href="#pick-a-game-and-plan-it-minutes-08" aria-label="Permalink to &quot;Pick a game and plan it (minutes 0–8)&quot;">​</a></h4><ol><li><p>Choose a game from the <a href="./game-menu.html">game menu</a>. New to JavaScript or the web? Pick a ★ Easy game.</p></li><li><p>In an assistant with a live preview (Gemini with Canvas, or Claude with Artifacts), start a <strong>new chat</strong>.</p></li><li><p><strong>Describe and Plan.</strong> Send this, filling in the brackets:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: Build a [game name] game that runs in the browser: [one-sentence description from the game menu].</span></span>
<span class="line"><span>Context: I know some programming ([your language]) but I&#39;m new to JavaScript and the web. I&#39;ll build it in small steps and save a working version after each step. It will live at game/index.html on my GitHub Pages site.</span></span>
<span class="line"><span>Constraints: One HTML file with the CSS and JavaScript inside it. No libraries, no external images, sounds or fonts. Playable with a keyboard or mouse on a laptop. Don&#39;t write any code yet.</span></span>
<span class="line"><span>Done when: You have proposed a plan of exactly 5 small steps. Each step adds one visible feature, can be tested in under a minute, and ends with a &quot;Done when&quot; line I can check. Step 1 is only the layout, with nothing moving yet.</span></span></code></pre></div></li><li><p><strong>Edit the plan.</strong> Compare it with the sample plan in the game menu. Is step 1 small? Can you test every step in a minute? Is anything too big (online leaderboards, multiplayer, accounts)? Tell the AI what to change, for example: <code>Split step 2 into two steps and drop the sound effects. Show me the final plan. Still no code.</code></p></li><li><p>Copy the final plan into your scratch note. You&#39;ll paste each step into the prompts below, and the plan into <code>PROMPTS.md</code> later.</p></li></ol><p>✅ <strong>Checkpoint:</strong> you have a 5-step plan, with a &quot;Done when&quot; for every step, that you changed at least once.</p><h4 id="the-loop-for-every-step-minutes-860" tabindex="-1">The loop for every step (minutes 8–60) <a class="header-anchor" href="#the-loop-for-every-step-minutes-860" aria-label="Permalink to &quot;The loop for every step (minutes 8–60)&quot;">​</a></h4><p>Repeat this for steps 1 to 5.</p><p><strong>Step.</strong> Send one step:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Goal: Do step [N] of the plan: [paste the step].</span></span>
<span class="line"><span>Context: [For step 1: &quot;We&#39;re starting from an empty file.&quot; Later: &quot;Here is my current game/index.html:&quot; then paste the complete file.]</span></span>
<span class="line"><span>Constraints: Change only what this step needs and keep everything that already works. Give me the complete updated file in one code block, not just the changed part.</span></span>
<span class="line"><span>Done when: [paste the step&#39;s &quot;Done when&quot; line].</span></span></code></pre></div><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Why paste the file each time? The AI only knows what is in its context window. It can&#39;t see your repository, and it doesn&#39;t know about changes you made elsewhere. If you&#39;re in the same chat and haven&#39;t changed anything, &quot;Context: the file from your last answer&quot; is fine.</p></div><p><strong>Test.</strong> In the preview, check the &quot;Done when&quot; line. Then try one <strong><a href="./../../resources/glossary.html#edge-case">edge case</a></strong>, a less common situation: click twice quickly, press a key that isn&#39;t a control, make the window narrow.</p><ul><li><strong>It works:</strong> go on to Read.</li><li><strong>It doesn&#39;t:</strong> say exactly what happened: <code>After this step, [what I did]. I expected [X]. Instead [Y]. Fix only that, and give me the complete file.</code></li><li><strong>Two failed fixes?</strong> That&#39;s the <strong>two-strikes rule</strong>: stop, start a fresh chat, paste your last working file from GitHub, and describe the problem more precisely.</li></ul><p><strong>Read.</strong> Copy the complete file. In github.dev, click into <code>game/index.html</code>, select everything (<strong>Ctrl+A</strong> / <strong>Cmd+A</strong>), paste, and save. Open <strong>Source Control</strong> and click the file to see the <strong>diff</strong>. Skim the red and green lines. Does the size of the change match the size of the step? If the AI changed something you didn&#39;t ask for, ask it why before you commit.</p><p><strong>Commit.</strong> Type a message that says what changed, a blank line and <code>Assisted-by: [tool]</code>, then <strong>Commit &amp; Push</strong>:</p><table tabindex="0"><thead><tr><th>Good messages</th><th>Bad messages</th></tr></thead><tbody><tr><td><code>Step 1: draw the board, snake and food</code></td><td><code>update</code></td></tr><tr><td><code>Step 2: snake moves with arrow keys</code></td><td><code>stuff</code></td></tr><tr><td><code>Fix: arrow keys no longer scroll the page</code></td><td><code>fixed it!!!</code></td></tr></tbody></table><p>After a minute, <code>https://[your-username].github.io/game/</code> shows the new version. You don&#39;t need to wait for it; keep going.</p><p>✅ <strong>Checkpoint (by minute 25):</strong> github.dev&#39;s Source Control shows no pending changes, and you&#39;ve made two commits, <code>Step 1: …</code> and <code>Step 2: …</code>.</p><p>✅ <strong>Checkpoint (at the buzzer):</strong> your last commit is a <strong>working</strong> version. If your current step is half-done and broken, don&#39;t commit it. Your game at <code>/game/</code> works up to at least step 2 or 3, with one commit per working step.</p><h3 id="part-b3--play-test-swap-and-checkpoint-share-10-min" tabindex="-1">Part B3 — Play-test swap and checkpoint share (10 min) <a class="header-anchor" href="#part-b3--play-test-swap-and-checkpoint-share-10-min" aria-label="Permalink to &quot;Part B3 — Play-test swap and checkpoint share (10 min)&quot;">​</a></h3><ol><li>Swap links with a neighbor. Play each other&#39;s game for <strong>two minutes without help</strong>. Watch them play yours, and write down the first thing that confused them. Don&#39;t fix it now: it&#39;s the first job in your <a href="./homework.html">homework</a>.</li><li>Post your game&#39;s live URL where your instructor asks, with the number of working-step commits in its History (for example &quot;Snake, 4 save points&quot;). Stuck? Post the exact blocker instead: that counts too.</li></ol><p><strong>Working alone?</strong> Play your own game for two minutes, trying to break it, and ask someone at home to try it later this week. Write the URL and the count in your scratch note.</p><h3 id="before-you-leave-studio-b" tabindex="-1">Before you leave Studio B <a class="header-anchor" href="#before-you-leave-studio-b" aria-label="Permalink to &quot;Before you leave Studio B&quot;">​</a></h3><ul><li>☐ Your game works at <code>https://[your-username].github.io/game/</code>, at least up to step 2 or 3.</li><li>☐ Its <strong>History</strong> shows one commit per working step, with clear messages.</li><li>☐ Your scratch note has the plan, what confused your play-tester, and anything you&#39;d prompt differently. You&#39;ll need them for <code>PROMPTS.md</code>.</li></ul><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>Fix</th></tr></thead><tbody><tr><td>Pressing <strong>.</strong> does nothing</td><td>Click an empty part of the page first (not a text box), or change <code>github.com</code> to <code>github.dev</code> in the address bar</td></tr><tr><td><strong>Commit &amp; Push</strong> is greyed out</td><td>Type a commit message, and save the file first (<strong>Ctrl+S</strong> / <strong>Cmd+S</strong>)</td></tr><tr><td>The <code>Assisted-by:</code> line doesn&#39;t show in the commit on github.com</td><td>It must be part of the commit message: in github.dev, on its own line after a blank line; on github.com, in <strong>Extended description</strong>. Add it to your next AI-helped commit; don&#39;t redo old ones</td></tr><tr><td>The game is blank after pasting</td><td>You pasted only part of the code, or chat formatting (<code>\`\`\`</code> lines). Ask for &quot;the complete file in one code block&quot; and use the copy button</td></tr><tr><td>The AI gives snippets (&quot;add this inside your update function&quot;)</td><td>Reply: <code>Give me the complete updated file in one code block.</code></td></tr><tr><td>Arrow keys or Space scroll the page</td><td>Ask: <code>Stop the game&#39;s keys from scrolling the page. Complete file, please.</code></td></tr><tr><td>Works in the preview, not on the live site</td><td>Wait a minute and hard-refresh (<strong>Ctrl+Shift+R</strong> / <strong>Cmd+Shift+R</strong>). Check the path is exactly <code>game/index.html</code>, lowercase, and the address ends in <code>/game/</code></td></tr><tr><td>Can&#39;t find <strong>History</strong></td><td>Open the file itself first (not the folder), then look at the top right of the code</td></tr><tr><td>github.dev says it can&#39;t push or there&#39;s a conflict</td><td>Copy your current code into a note, close github.dev, reopen it, and paste your change again</td></tr><tr><td>You hit an assistant&#39;s usage limit</td><td>Switch to another assistant and paste your current file from GitHub. See <a href="./../../resources/troubleshooting.html#i-ran-out-of-free-credits">I ran out of free credits</a></td></tr><tr><td>You&#39;re stuck on step 1 after 15 minutes</td><td>Switch to a ★ Easy game from the menu and use its sample plan as your plan. Tell your instructor</td></tr></tbody></table><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><ul><li><strong>Main assistant down:</strong> use a fallback from the <a href="./../../TOOLS.html">Tool Handout</a>. Paste your current <code>game/index.html</code> from GitHub into the new chat first, because the new tool starts with an empty context window.</li><li><strong>No assistant with a preview:</strong> commit each step and test it on your live site a minute later.</li><li><strong>github.dev won&#39;t open:</strong> edit on github.com instead. Open the file, click the <strong>pencil</strong> icon, paste, then <strong>Commit changes…</strong> (the <code>Assisted-by:</code> line goes in <strong>Extended description</strong>). To create <code>game/index.html</code>, use <strong>Add file → Create new file</strong> and type <code>game/index.html</code> as the name.</li></ul>`,71)])])}const u=e(s,[["render",i]]);export{m as __pageData,u as default};
